'use client';

import * as React from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from '@/components/ui/dialog';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { Button } from '@/components/ui/button';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Badge } from '@/components/ui/badge';
import { Skeleton } from '@/components/ui/skeleton';
import { getSalesHistory } from '@/lib/api';
import { GroupedSale } from '@/lib/types';
import { format } from 'date-fns';
import { es } from 'date-fns/locale';
import { Eye, Edit, Trash2 } from 'lucide-react';

interface SalesHistoryDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onViewReceipt: (sale: GroupedSale) => void;
  onEditSale: (sale: GroupedSale) => void;
  refetchKey: number;
}

export function SalesHistoryDialog({ open, onOpenChange, onViewReceipt, onEditSale, refetchKey }: SalesHistoryDialogProps) {
  const [history, setHistory] = React.useState<GroupedSale[]>([]);
  const [isLoading, setIsLoading] = React.useState(false);

  const fetchHistory = React.useCallback(async () => {
    setIsLoading(true);
    try {
      const data = await getSalesHistory();
      setHistory(data);
    } catch (error) {
      // handled in api layer
    } finally {
      setIsLoading(false);
    }
  }, []);

  React.useEffect(() => {
    if (open) {
      fetchHistory();
    }
  }, [open, refetchKey, fetchHistory]);

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-4xl">
        <DialogHeader>
          <DialogTitle>Historial de Ventas</DialogTitle>
          <DialogDescription>Consulta, edita o anula tus ventas pasadas.</DialogDescription>
        </DialogHeader>
        <ScrollArea className="h-[60vh] border rounded-md">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Cliente</TableHead>
                <TableHead>Fecha</TableHead>
                <TableHead>Total</TableHead>
                <TableHead>Estado</TableHead>
                <TableHead className="text-right">Acciones</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {isLoading ? (
                Array.from({ length: 5 }).map((_, i) => (
                  <TableRow key={i}>
                    <TableCell colSpan={5}><Skeleton className="h-8 w-full" /></TableCell>
                  </TableRow>
                ))
              ) : history.length > 0 ? (
                history.map((sale) => (
                  <TableRow key={sale.transaction_id}>
                    <TableCell>
                      <p className="font-medium">{sale.entity_name || 'Cliente General'}</p>
                      <p className="text-sm text-muted-foreground">{sale.document_number}</p>
                    </TableCell>
                    <TableCell>{format(new Date(sale.transaction_date), 'P', { locale: es })}</TableCell>
                    <TableCell>${sale.total.toFixed(2)}</TableCell>
                    <TableCell><Badge variant={sale.status === 'Activo' ? 'default' : 'destructive'}>{sale.status}</Badge></TableCell>
                    <TableCell className="text-right">
                      <div className="flex justify-end gap-2">
                        <Button variant="outline" size="sm" onClick={() => onViewReceipt(sale)}><Eye className="mr-2 h-4 w-4" />Recibo</Button>
                        <Button variant="secondary" size="sm" onClick={() => onEditSale(sale)} disabled={sale.status !== 'Activo'}><Edit className="mr-2 h-4 w-4" />Editar</Button>
                        <Button variant="destructive" size="sm" disabled={sale.status !== 'Activo'}><Trash2 className="mr-2 h-4 w-4" />Anular</Button>
                      </div>
                    </TableCell>
                  </TableRow>
                ))
              ) : (
                <TableRow>
                  <TableCell colSpan={5} className="text-center h-24">No se encontraron ventas.</TableCell>
                </TableRow>
              )}
            </TableBody>
          </Table>
        </ScrollArea>
      </DialogContent>
    </Dialog>
  );
}
